--region import
local util = require 'XLua.util'
local cs_coroutine = require 'XLua.cs_coroutine'
---@type ActivityUtils
local ActivityUtils  = import("Game.Activity.ActivityUtils")
--endregion import

--region define
local CoWait = CS.Engine.Lib.CoWait
local KTool = CS.Engine.Lib.KTool
local UIActivityMultipleSignDialog = "Game.UI.ActivityMainDialog.UIActivityMultipleSignDialog"
local UIActivityMainSingleSignNode = "Game.UI.ActivityMainDialog.UIActivityMainSingleSignNode"

local SignPanelType = {
    SINGLE   = 1,
    MULTIPLE = 2
}
--endregion define

---@class ActivitySignNode
---@field MultipleSignPanel                UnityEngine.RectTransform
---@field SingleSignPanel                  UnityEngine.RectTransform
local ActivitySignNode = Class("ActivitySignNode")

--region lifecycle
function ActivitySignNode:__init()
    self._activityDojo = nil
    self._signPrefab = nil
    self._createNodeCo = nil
end

function ActivitySignNode:__delete()
    self.controller = nil
    self._activityDojo = nil
    self._signPrefab = nil
    self._createNodeCo = nil
end

function ActivitySignNode:Awake()
end 

function ActivitySignNode:OnDestroy()
    if self._createNodeCo ~= nil then
        cs_coroutine.stop(self._createNodeCo)
    end
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end
--endregion lifecycle

--region public
---刷新自身
---@param activityDojo ActivityDojo
function ActivitySignNode:Refresh(activityDojo)
    self._activityDojo = activityDojo
    GameUtils.Request(
        Interfaces.ActivityAccumulativeLogin,
        {activityUuid = activityDojo.id},
        Bind(self, self.SignHomeResponseHandler)
    )
end

function ActivitySignNode:RefreshCurrencyBarInfo()
    if checkInt(self.panelType) == SignPanelType.SINGLE then
        local prefab = self._signPrefab or self.SingleSignPanel
        local scr = CfUtils.GetLuaScr(prefab, UIActivityMainSingleSignNode)
        if scr.RefreshCurrencyBarInfo then
            scr:RefreshCurrencyBarInfo()
        end
    elseif checkInt(self.panelType) == SignPanelType.MULTIPLE then
        local prefab = self._signPrefab or self.MultipleSignPanel
        local scr = CfUtils.GetLuaScr(self.MultipleSignPanel, UIActivityMultipleSignDialog)
        if scr.RefreshCurrencyBarInfo then
            scr:RefreshCurrencyBarInfo()
        end
    end
end
--endregion public

--region private
---签到home response处理
function ActivitySignNode:SignHomeResponseHandler(request, response)
    if self._createNodeCo ~= nil then
        cs_coroutine.stop(self._createNodeCo)
    end
    self._createNodeCo = cs_coroutine.start(function()
        self.panelType = checkInt(response.data.accumulativePayConf.taskUI)
        local prefabPattern = self._activityDojo.prefab
        if self.panelType == SignPanelType.SINGLE then
            local prefab = nil
            if prefabPattern then
                if self._signPrefab then
                    prefab = self._signPrefab
                else
                    local path = string.format("Prefabs/Activity/SingleSignPanel%s.prefab", tostring(prefabPattern))
                    prefab = GameUtils.LoadBundleAsync(path, self.controller.gameObject, false)
                    self._signPrefab = prefab
                end
            else
                KTool.SetActive(self.SingleSignPanel.gameObject, true)
                prefab = self.SingleSignPanel
            end
            local scr = CfUtils.GetLuaScr(prefab, UIActivityMainSingleSignNode)
            scr:Refresh(self._activityDojo, response.data)
        elseif self.panelType == SignPanelType.MULTIPLE then
            local prefab = nil
            if prefabPattern then
                if self._signPrefab then
                    prefab = self._signPrefab
                else
                    local path = string.format("Prefabs/Activity/MultipleSignPanel%s.prefab", tostring(prefabPattern))
                    prefab = GameUtils.LoadBundleAsync(path, self.controller.gameObject, false)
                    self._signPrefab = prefab
                end
            else
                KTool.SetActive(self.MultipleSignPanel.gameObject, true)
                prefab = self.MultipleSignPanel
            end
            local scr = CfUtils.GetLuaScr(prefab, UIActivityMultipleSignDialog)
            scr:Refresh(self._activityDojo, response.data)
        end
    end)
end
--endregion private

return ActivitySignNode